#!/usr/bin/env bash

# This script was generated by OpenAI ChatGPT at the user's request.

set -euo pipefail

if [[ $# -ne 3 ]]; then
  echo "Usage: $0 OWNER/REPO PR_NUMBER RULESET_NAME" >&2
  exit 1
fi

for dependency in gh jq; do
  if ! command -v "$dependency" >/dev/null 2>&1; then
    echo "Error: $dependency is required but was not found in PATH." >&2
    exit 1
  fi
done

repo="$1"
pr="$2"
ruleset_name="$3"

workdir="$(mktemp -d)"
trap 'rm -rf "$workdir"' EXIT

# Fetch every page, excluding inherited organization rulesets.
gh api --paginate \
  "repos/$repo/rulesets?includes_parents=false&per_page=100" \
  > "$workdir/rulesets.json"

# Match the exact name, safely handling spaces and special characters.
jq -s --arg name "$ruleset_name" '
  [.[][] | select(.name == $name)]
' "$workdir/rulesets.json" > "$workdir/matches.json"

match_count="$(jq 'length' "$workdir/matches.json")"

if [[ "$match_count" -ne 1 ]]; then
  echo "Error: expected one repository ruleset named '$ruleset_name'; found $match_count." >&2
  exit 1
fi

ruleset_id="$(jq -r '.[0].id' "$workdir/matches.json")"
endpoint="repos/$repo/rulesets/$ruleset_id"

# gh pr checks can exit nonzero for failed or pending checks.
if gh pr checks "$pr" --repo "$repo" --json name \
    > "$workdir/checks.json"; then
  :
else
  result=$?
  case "$result" in
    1|8) ;;  # Validate the output below before proceeding.
    *) exit "$result" ;;
  esac
fi

# Refuse to update protection with an empty or invalid check list.
jq -e '
  type == "array" and length > 0 and
  all(.[]; (.name | type == "string" and length > 0))
' "$workdir/checks.json" >/dev/null

gh api "$endpoint" > "$workdir/ruleset.json"

# Inherited organization rulesets require a different API endpoint.
jq -e '.source_type == "Repository"' \
  "$workdir/ruleset.json" >/dev/null || {
    echo "This script requires a repository-owned ruleset." >&2
    exit 1
  }

jq --slurpfile observed "$workdir/checks.json" '
  ($observed[0] | map({context: .name}) | unique_by(.context)) as $checks |
  {
    rules: (
      .rules |
      if any(.[]; .type == "required_status_checks") then
        map(
          if .type == "required_status_checks" then
            (.parameters.required_status_checks // []) as $old |
            .parameters.required_status_checks = (
              $checks | map(
                . as $check |
                (
                  $old |
                  map(select(
                    (.context | ascii_downcase) ==
                    ($check.context | ascii_downcase)
                  )) |
                  first
                ) // $check
              )
            )
          else . end
        )
      else
        . + [{
          type: "required_status_checks",
          parameters: {
            strict_required_status_checks_policy: false,
            required_status_checks: $checks
          }
        }]
      end
    )
  }
' "$workdir/ruleset.json" > "$workdir/update.json"

gh api --method PUT "$endpoint" \
  --input "$workdir/update.json" >/dev/null

echo "Updated ruleset $ruleset_id with these required checks:"
jq -r '.[].name' "$workdir/checks.json" | sort -u
